package com.circlenet.domain.finance;
import java.security.Principal;import java.time.YearMonth;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/finance") public class FinanceController{private final FinanceService service;public FinanceController(FinanceService s){service=s;}@GetMapping("/summary")public FinanceService.Summary summary(Principal p,@RequestParam(required=false)String month){return service.summary(id(p),month==null?YearMonth.now():YearMonth.parse(month));}@PostMapping("/transactions")public FinanceService.Transaction add(Principal p,@RequestBody FinanceService.Input input){return service.add(id(p),input);}@DeleteMapping("/transactions/{id}")public ResponseEntity<Void> delete(Principal p,@PathVariable Long id){service.delete(id(p),id);return ResponseEntity.noContent().build();}private Long id(Principal p){return Long.valueOf(p.getName());}}
